                ],
                'POWER' => [
                    'tpl' => 'power({numericCast:0}, {numericCast:1})',
                    'ret' => 'NUM',
                    'caveat' => 'numeric-scale',
                ],
                'ISNUM' => [
                    'tpl' => '({textCast:0} ~ \'^-?[0-9]+(\\.[0-9]+)?$\')',
